def check_squares(target):
    # Check for 1 square
    for i in range(int(target**0.5) + 1):
        if i*i == target:
            return 1

    # Check for 2 squares
    for i in range(int(target**0.5) + 1):
        j_sq = target - i*i
        j = int(j_sq**0.5)
        if j*j == j_sq:
            return 2

    # Check for 3 squares (brute force up to sqrt(target))
    for i in range(int(target**0.5) + 1):
        for j in range(i, int((target - i*i)**0.5) + 1):
            k_sq = target - i*i - j*j
            k = int(k_sq**0.5)
            if k*k == k_sq:
                return 3

    # If not 1, 2, or 3, it must be 4 or more (Lagrange guarantees 4)
    return 4

target = 7
result = check_squares(target)
print(f"Minimum squares needed for {target}: {result}")

def is_sum_of_m_squares(N, m):
    # Check if N can be written as the sum of m squares of integers
    # We only check small values relevant to the problem constraints (N=7)
    if N < 0:
        return False

    # We only need to check up to floor(sqrt(N)) for each square
    squares = [i*i for i in range(int(N**0.5) + 1)]

    def can_sum(target, count, current_list):
        if count == 1:
            return target in current_list
        if count == 0:
            return target == 0

        # Iterate over all possible squares from the list
        for s in current_list:
            if target - s >= 0:
                if can_sum(target - s, count - 1, current_list):
                    return True
        return False

    # Since we allow negative integers, we use squares of integers (0, 1, 4, 9, ...)
    return can_sum(N, m, squares)

